$ErrorActionPreference = "Stop"

$ProjectRoot = (Get-Location).Path
$Target = Join-Path $ProjectRoot "src\vista3d_tfg\integration\nv_segment.py"
$WindowsTest = Join-Path $ProjectRoot "tests\test_nv_segment_windows_runtime.py"

if (-not (Test-Path (Join-Path $ProjectRoot "pyproject.toml"))) {
    throw "Run this script from the tfg-vista3d-medical-imaging project root."
}

if (-not (Test-Path $Target)) {
    throw "Target file not found: $Target"
}

$Timestamp = Get-Date -Format "yyyyMMdd-HHmmss"
$Backup = "$Target.block08b-backup-$Timestamp"

Copy-Item $Target $Backup -Force
Write-Host "Backup created: $Backup"

$NvSegmentBase64 = @'

'@

$WindowsTestBase64 = @'

'@

[System.IO.File]::WriteAllBytes(
    $Target,
    [System.Convert]::FromBase64String($NvSegmentBase64.Trim())
)

[System.IO.File]::WriteAllBytes(
    $WindowsTest,
    [System.Convert]::FromBase64String($WindowsTestBase64.Trim())
)

Write-Host "Replaced: $Target"
Write-Host "Created/replaced: $WindowsTest"
Write-Host ""
Write-Host "Checking Python syntax..."

python -m py_compile $Target
python -m py_compile $WindowsTest

if ($LASTEXITCODE -ne 0) {
    throw "Python syntax validation failed."
}

Write-Host "Syntax check PASSED."
Write-Host ""
Write-Host "Conda executable visible to this process:"
Write-Host "CONDA_EXE=$env:CONDA_EXE"
Write-Host "CONDA_PREFIX=$env:CONDA_PREFIX"
Write-Host ""
Write-Host "Block 08B deterministic repair PASSED."
